Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 12;
const int INF = 1000000;
const int MAXNODE = 2 * 12 * 12 + 5;
const int MAXEDGE = 50000;

int N,T;
char grid1[MAXN][MAXN], grid2[MAXN][MAXN];
int distZ[MAXN][MAXN];
int good[MAXN][MAXN][MAXN][MAXN];

int dirx[4] = {-1,1,0,0};
int diry[4] = {0,0,-1,1};

int head[MAXNODE], nxt[MAXEDGE], to[MAXEDGE], cap[MAXEDGE], flow[MAXEDGE];
int ecnt;

void add_edge(int u,int v,int c) {
    to[ecnt]=v; cap[ecnt]=c; flow[ecnt]=0; nxt[ecnt]=head[u]; head[u]=ecnt++;
    to[ecnt]=u; cap[ecnt]=0; flow[ecnt]=0; nxt[ecnt]=head[v]; head[v]=ecnt++;
}

int nNodes, src, snk;
int levelArr[MAXNODE], curArr[MAXNODE], qarr[MAXNODE];

bool bfs() {
    int h=0,t=0;
    qarr[t++]=src;
    memset(levelArr,-1,nNodes*sizeof(levelArr[0]));
    levelArr[src]=0;
    while(h<t && levelArr[snk]==-1) {
        int v=qarr[h++];
        for(int id=head[v]; id!=-1; id=nxt[id]) {
            int w=to[id];
            if(levelArr[w]==-1 && flow[id] < cap[id]) {
                qarr[t++]=w;
                levelArr[w]=levelArr[v]+1;
            }
        }
    }
    return levelArr[snk]!=-1;
}

int dfs(int v,int pushed) {
    if(!pushed) return 0;
    if(v==snk) return pushed;
    for(int &id=curArr[v]; id!=-1; id=nxt[id]) {
        int w=to[id];
        if(levelArr[w]!=levelArr[v]+1) continue;
        int got=dfs(w, min(pushed, cap[id]-flow[id]));
        if(got) {
            flow[id]+=got;
            flow[id^1]-=got;
            return got;
        }
    }
    return 0;
}

int dinic() {
    int ans=0;
    while(bfs()) {
        for(int i=0;i<nNodes;i++) curArr[i]=head[i];
        while(int pushed=dfs(src,INF)) ans+=pushed;
    }
    return ans;
}

bool pathExists(int sx,int sy,int tx,int ty) {
    if(grid1[sx][sy]=='Y'||grid1[sx][sy]=='Z'||grid1[tx][ty]=='Y'||grid1[tx][ty]=='Z')
        return false;

    int dist[MAXN][MAXN];
    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++)
            dist[i][j]=INF;

    queue<pair<int,int>> q;
    dist[sx][sy]=0;
    q.push({sx,sy});

    while(!q.empty()) {
        int x=q.front().first, y=q.front().second;
        q.pop();
        if(x==tx && y==ty) return true;
        if(dist[x][y] >= T || dist[x][y] >= distZ[x][y]) continue;
        for(int d=0;d<4;d++) {
            int nx=x+dirx[d], ny=y+diry[d];
            if(nx>=0 && nx<N && ny>=0 && ny<N &&
               grid1[nx][ny]!='Y' && grid1[nx][ny]!='Z' &&
               dist[nx][ny]==INF &&
               dist[x][y]+1 <= distZ[nx][ny]) {
                dist[nx][ny]=dist[x][y]+1;
                q.push({nx,ny});
            }
        }
    }
    return false;
}

int main() {
    scanf("%d%d",&N,&T);
    for(int i=0;i<N;i++) scanf("%s",grid1[i]);
    getchar();
    for(int i=0;i<N;i++) scanf("%s",grid2[i]);

    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++)
            distZ[i][j]=INF;

    queue<pair<int,int>> q;
    for(int x=0;x<N;x++)
        for(int y=0;y<N;y++)
            if(grid1[x][y]=='Z') {
                for(int d=0;d<4;d++) {
                    int nx=x+dirx[d], ny=y+diry[d];
                    if(nx>=0 && nx<N && ny>=0 && ny<N && grid1[nx][ny]!='Y') {
                        distZ[nx][ny]=1;
                        q.push({nx,ny});
                    }
                }
            }

    while(!q.empty()) {
        int x=q.front().first, y=q.front().second;
        q.pop();
        for(int d=0;d<4;d++) {
            int nx=x+dirx[d], ny=y+diry[d];
            if(nx>=0 && nx<N && ny>=0 && ny<N &&
               grid1[nx][ny]!='Y' && grid1[nx][ny]!='Z' &&
               distZ[nx][ny]==INF) {
                distZ[nx][ny]=distZ[x][y]+1;
                q.push({nx,ny});
            }
        }
    }

    for(int x1=0;x1<N;x1++)
        for(int y1=0;y1<N;y1++)
            for(int x2=0;x2<N;x2++)
                for(int y2=0;y2<N;y2++)
                    good[x1][y1][x2][y2] = pathExists(x1,y1,x2,y2) ? 1 : 0;

    src=0;
    snk=2*N*N+1;
    nNodes=2*N*N+2;

    memset(head,-1,sizeof(head));
    ecnt=0;

    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++) {
            if(grid1[i][j]>'0' && grid1[i][j]<='9')
                add_edge(src,1+i*N+j,grid1[i][j]-'0');
            if(grid2[i][j]>'0' && grid2[i][j]<='9')
                add_edge(N*N+1+i*N+j,snk,grid2[i][j]-'0');
        }

    for(int x1=0;x1<N;x1++)
        for(int y1=0;y1<N;y1++)
            for(int x2=0;x2<N;x2++)
                for(int y2=0;y2<N;y2++)
                    if(good[x1][y1][x2][y2])
                        add_edge(1+x1*N+y1, N*N+1+x2*N+y2, INF);

    printf("%d\n",dinic());
    return 0;
}
